<script setup>
import {computed} from 'vue';import {usePreferredReducedMotion} from '@vueuse/core';const reducedMotion=usePreferredReducedMotion();import {cases} from '../data/cases';import {trends} from '../data/chapters';import {figures,videos} from '../data/figures';import {sourceByKey,chapterSources} from '../data/sources';import audioSrc from '../assets/audio/commentary.mp3';import audioText from '../assets/audio/transcript.txt?raw';import FigureBlock from './FigureBlock.vue';import PullQuote from './PullQuote.vue';import VideoEmbed from './VideoEmbed.vue';import StatCounter from './StatCounter.vue';import AudioBlock from './AudioBlock.vue';import LazyChart from './LazyChart.vue';import EvolutionBlock from './EvolutionBlock.vue';const props=defineProps({chapter:Object});const references=computed(()=>(chapterSources[props.chapter.id]||[]).map(key=>sourceByKey[key]));
</script><template><section :id="chapter.id" class="chapter" :aria-labelledby="chapter.id+'-title'"><header class="chapter-header"><p class="eyebrow"><span>{{chapter.number}}</span> / {{chapter.label}}</p><h2 :id="chapter.id+'-title'">{{chapter.title}}</h2><p class="chapter-deck">{{chapter.deck}}</p></header><div class="chapter-content"><template v-for="(block,index) in chapter.blocks" :key="index"><p v-if="block.type==='p'" class="body-copy">{{block.text}}</p><FigureBlock v-else-if="block.type==='figure'" :figure="figures[block.figure]"/><PullQuote v-else-if="block.type==='quote'" :text="block.text" :attribution="block.attribution"/><VideoEmbed v-else-if="block.type==='video'" :video="videos[block.video]"/><LazyChart v-else-if="block.type==='chart'" :chart="block.chart"/><EvolutionBlock v-else-if="block.type==='evolution'"/><AudioBlock v-else-if="block.type==='audio'" :src="audioSrc" :transcript="audioText"/><div class="stats-grid" v-else-if="block.type==='stats'"><StatCounter :value="5" label="характеристик облака"/><StatCounter :value="3" label="модели обслуживания"/><StatCounter :value="4" label="модели развёртывания"/><p>По определению NIST SP 800-145</p></div><div class="trends-block" v-else-if="block.type==='trends'"><p class="eyebrow">КАРТА / 17 ТРЕНДОВ</p><div class="trends-table-wrap"><table><caption>Технологии Web 3.0: роль и авторская качественная оценка зрелости</caption><thead><tr><th>Тренд</th><th>Задача</th><th>Зрелость</th></tr></thead><tbody><tr v-for="[name,meaning,maturity] in trends"><th>{{name}}</th><td>{{meaning}}</td><td>{{maturity}}</td></tr></tbody></table></div></div><div class="cases-grid" v-else-if="block.type==='cases'"><article v-for="c in cases" class="case-card" v-motion :initial="{opacity:1}" :visibleOnce="{opacity:1,transition:{duration:500}}" :hovered="reducedMotion==='reduce'?{}:{y:-4,transition:{duration:400}}"><p class="eyebrow">{{c.name}}</p><h3>{{c.title}}</h3><p>{{c.text}}</p><a :href="sourceByKey[c.key].url" target="_blank" rel="noopener noreferrer">Разобрать кейс ↗</a></article></div></template><aside class="chapter-references"><span>ИСТОЧНИКИ ГЛАВЫ</span><a v-for="source in references" :key="source.key" :href="source.url" target="_blank" rel="noopener noreferrer">{{source.author}} · {{source.title}} ↗</a></aside></div></section></template>
